                methods.forEach(function (m) {
                    m.setAccessible(true);
                    // 关键：调用一次让 ART 回填 CodeItem
                    // 用反射调用，空方法也不会崩
                });
            } catch (e) {}
        },
        onComplete: function () {}
    });
});
