#include <ntifs.h>

#define DEV_NAME   L"\\Device\\EacRw"
#define SYM_NAME   L"\\??\\EacRw"
#define IOCTL_READ  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_BASE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQ {
    ULONG  pid;
    ULONG64 addr;
    ULONG  size;
    UCHAR  buf[4096];
} RW_REQ, *PRW_REQ;

static PDEVICE_OBJECT g_Dev = NULL;

static NTSTATUS DoCopy(PRW_REQ req, BOOLEAN write) {
    PEPROCESS src = NULL, dst = NULL;
    NTSTATUS st;
    if (!req || req->size == 0 || req->size > sizeof(req->buf)) return STATUS_INVALID_PARAMETER;
    st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->pid, &src);
    if (!st) {
        dst = PsGetCurrentProcess();
        if (write)
            st = MmCopyVirtualMemory(dst, req->buf, src, (PVOID)(ULONG_PTR)req->addr, req->size, KernelMode, NULL);
        else
            st = MmCopyVirtualMemory(src, (PVOID)(ULONG_PTR)req->addr, dst, req->buf, req->size, KernelMode, NULL);
        ObDereferenceObject(src);
    }
    return st;
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG code = sp->Parameters.DeviceIoControl.IoControlCode;
    PVOID sys = irp->AssociatedIrp.SystemBuffer;
    ULONG inlen = sp->Parameters.DeviceIoControl.InputBufferLength;
    switch (code) {
    case IOCTL_READ:  st = DoCopy((PRW_REQ)sys, FALSE); break;
    case IOCTL_WRITE: st = DoCopy((PRW_REQ)sys, TRUE);  break;
    case IOCTL_BASE: {
        PEPROCESS p = NULL;
        if (!NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)((PRW_REQ)sys)->pid, &p))) break;
        ((PRW_REQ)sys)->addr = (ULONG64)PsGetProcessSectionBaseAddress(p);
        ObDereferenceObject(p);
        st = STATUS_SUCCESS;
        break;
    }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = (code == IOCTL_READ || code == IOCTL_WRITE) ? inlen : sizeof(RW_REQ);
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static VOID Unload(PDRIVER_OBJECT d) {
    UNICODE_STRING s;
    RtlInitUnicodeString(&s, SYM_NAME); IoDeleteSymbolicLink(&s);
    if (g_Dev) IoDeleteDevice(g_Dev);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT d, PUNICODE_STRING r) {
    UNICODE_STRING dn, sn;
    PDEVICE_OBJECT dev = NULL;
    NTSTATUS st;
    RtlInitUnicodeString(&dn, DEV_NAME); RtlInitUnicodeString(&sn, SYM_NAME);
    st = IoCreateDevice(d, 0, &dn, FILE_DEVICE_UNKNOWN, FILE_DEVICE_SECURE_OPEN, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;
    st = IoCreateSymbolicLink(&sn, &dn);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }
    g_Dev = dev;
    d->MajorFunction[IRP_MJ_CREATE] = Dispatch;
    d->MajorFunction[IRP_MJ_CLOSE]  = Dispatch;
    d->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    d->DriverUnload = Unload;
    dev->Flags &= ~DO_DEVICE_INITIALIZING;
    return STATUS_SUCCESS;
}
