    SIZE_T done = 0;

    st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &dstProc);
    if (!NT_SUCCESS(st)) return st;

    srcProc = PsGetCurrentProcess();
    if (bWrite) {
        // 写：把用户 buffer 的内容写进目标
        st = MmCopyVirtualMemory(srcProc, req->Buffer, dstProc, req->Address,
                                 req->Size, KernelMode, &done);
    } else {
        // 读：把目标内容拷到用户 buffer
        st = MmCopyVirtualMemory(dstProc, req->Address, srcProc, req->Buffer,
                                 req->Size, KernelMode, &done);
    }
    req->Returned = done;
    ObDereferenceObject(dstProc);
    return st;
}

static NTSTATUS DispatchCreate(PDEVICE_OBJECT dev, PIRP irp) {
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp)
{
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG code = sp->Parameters.DeviceIoControl.IoControlCode;

    if (sp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
        PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
        switch (code) {
        case IOCTL_READ:  st = DoReadWrite(req, FALSE); break;
        case IOCTL_WRITE: st = DoReadWrite(req, TRUE);  break;
        case IOCTL_BASE: {
            // 取模块基址（示例：按 PID + 模块名遍历 PEB / VAD）
            st = STATUS_SUCCESS;
            break;
        }
        default: break;
        }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = (st == STATUS_SUCCESS) ? sizeof(RW_REQ) : 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    PDEVICE_OBJECT dev = NULL;
    UNICODE_STRING devName, symName;

    RtlInitUnicodeString(&devName, DEV_NAME);
    RtlInitUnicodeString(&symName, SYM_NAME);

    NTSTATUS st = IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN,
                                 FILE_DEVICE_SECURE_OPEN, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    st = IoCreateSymbolicLink(&symName, &devName);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    drv->MajorFunction[IRP_MJ_CREATE] = DispatchCreate;
    drv->MajorFunction[IRP_MJ_CLOSE]  = DispatchCreate;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchIoctl;

    KdPrint(("[drv] loaded\n"));
    return STATUS_SUCCESS;
}
```

