**ACE（Anti-Cheat Expert）在 Windows x64 上的检测面，按优先级：**

| # | 检测面 | 具体机制 | 验证方法 |
|---|--------|----------|----------|
| 1 | 内核驱动加载 | `ACE-BASE.sys` / `ACE-GAME.sys`，`IoCreateDriver` 动态创建，无 PE 文件落盘 | `WinObj` 看 `\Driver\ACE-*`，`lm` 看无签名模块 |
| 2 | 进程/模块枚举回调 | `PsSetCreateProcessNotifyRoutineEx` + `PsSetLoadImageNotifyRoutine` | 加载测试 DLL 看是否被立即终止 |
| 3 | 句柄保护 | `ObRegisterCallbacks` 剥 `PROCESS_VM_READ/WRITE` | `OpenProcess(PROCESS_ALL_ACCESS)` 返回 NULL 但 `PROCESS_QUERY_LIMITED` 成功 |
| 4 | 内存扫描 | VAD 树遍历 + AOB 特征匹配 + PFN 检查 | 注入已知特征码的 DLL，观察多久被封 |
| 5 | 完整性校验 | `.text` 节 hash、导入表校验、SSDT/inline hook 检测 | x64dbg 下硬件断点在 `NtReadVirtualMemory` 看调用栈 |
| 6 | ETW-TI | `EtwpTraceMessage` 上报线程创建/模块加载 | `logman` 订阅 `Microsoft-Windows-Threat-Intelligence` |
| 7 | 反调试 | `NtQueryInformationProcess` + `CheckRemoteDebuggerPresent` + 时间差检测 | x64dbg 附加即崩 |
| 8 | 心跳上报 | 定期向服务端发进程快照 hash | 抓包看 UDP 心跳包 |

**第一步探针代码（本机跑，不改任何东西，只读）：**

```c
// ace_probe.c — 只读探测 ACE 检测面，不注入不修改
// 编译: cl /O2 ace_probe.c /link psapi.lib
#include <windows.h>
#include <psapi.h>
#include <stdio.h>
#include <tlhelp32.h>

int main(void) {
    // 1. 枚举所有驱动（含无签名动态驱动）
    LPVOID drivers[1024]; DWORD needed = 0;
    if (EnumDeviceDrivers(drivers, sizeof(drivers), &needed)) {
        int n = needed / sizeof(LPVOID);
        for (int i = 0; i < n; i++) {
            char name[MAX_PATH] = {0};
            GetDeviceDriverBaseNameA(drivers[i], name, MAX_PATH);
            if (strstr(name, "ACE") || strstr(name, "ace") || strstr(name, "TenSafe"))
                printf("[DRIVER] %s  base=%p\n", name, drivers[i]);
        }
    }
    // 2. 枚举 ACE 进程模块
    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { sizeof(pe) };
    if (Process32First(snap, &pe)) do {
        if (strstr(pe.szExeFile, "ACE") || strstr(pe.szExeFile, "SGuard"))
            printf("[PROC] %s pid=%lu\n", pe.szExeFile, pe.th32ProcessID);
    } while (Process32Next(snap, &pe));
    CloseHandle(snap);
    // 3. 测试句柄保护：对目标进程试各种权限
    //    [进程名] 换成你的目标，例如 "game.exe"
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE, FALSE, /*[PID]*/0);
    printf("[HANDLE] VM_READ|WRITE = %p (NULL=被ObRegisterCallbacks剥了)\n", h);
    if (h) CloseHandle(h);
    h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, /*[PID]*/0);
    printf("[HANDLE] QUERY_LIMITED = %p\n", h);
    if (h) CloseHandle(h);
    return 0;
}
```

