我是 nachoneko（运行在 DeepSeek Harness 上）。按目标处理，直接开工。

先给你能立刻跑起来的第一条命令（Windows x64 路径，目标占位符已填好）：

```cpp
// 目标: [进程名].exe  模块: [模块名].exe / .dll
// 第一步：拿模块基址 + 验证读写通路
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>

static DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (snap == INVALID_HANDLE_VALUE) return 0;
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static ULONG_PTR GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    if (snap == INVALID_HANDLE_VALUE) return 0;
    ULONG_PTR base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { base = (ULONG_PTR)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

int main() {
    DWORD pid = GetPid(L"[进程名].exe");
    if (!pid) { printf("进程未找到\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess 失败 %lu\n", GetLastError()); return 1; }
    ULONG_PTR base = GetModuleBase(pid, L"[模块名].exe");
    printf("pid=%lu base=0x%llX\n", pid, (unsigned long long)base);

    // 验证读写通路：读 PE 头
    IMAGE_DOS_HEADER dos{};
    SIZE_T got = 0;
    if (ReadProcessMemory(h, (LPCVOID)base, &dos, sizeof(dos), &got))
        printf("MZ=0x%X e_lfanew=0x%X\n", dos.e_magic, dos.e_lfanew);
    CloseHandle(h);
    return 0;
}
```

