`KbDrv.c`（核心：`MmCopyVirtualMemory` 读写 + 模块基址查询）：
```c
#include "KbDrv.h"

static NTSTATUS
KbCopyMemory(
    _In_ ULONG Pid,
    _In_ ULONGLONG Src,
    _In_ ULONGLONG Dst,
    _In_ ULONG Size,
    _In_ KPROCESSOR_MODE Mode,
    _Out_ PSIZE_T Done
)
{
    PEPROCESS Process = NULL;
    NTSTATUS Status = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)Pid, &Process);
    if (!NT_SUCCESS(Status)) return Status;

    Status = MmCopyVirtualMemory(
        Process, (PVOID)Src,
        PsGetCurrentProcess(), (PVOID)Dst,
        Size, Mode, Done);

    ObDereferenceObject(Process);
    return Status;
}

static NTSTATUS
KbFindModule(_Inout_ PKB_MODULE Mod)
{
    PEPROCESS Process = NULL;
    NTSTATUS Status = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)Mod->Pid, &Process);
    if (!NT_SUCCESS(Status)) return Status;

    KAPC_STATE Apc;
    KeStackAttachProcess(Process, &Apc);

    PVOID Base = NULL;
    SIZE_T Size = 0;
    UNICODE_STRING Name;
    RtlInitUnicodeString(&Name, Mod->Name);
    Status = ZwQueryVirtualMemory(
        ZwCurrentProcess(), NULL, MemoryBasicInformation, NULL, 0, NULL);

    // 真正查模块用 PE 遍历 PEB->Ldr，或用 PsGetProcessSectionBaseAddress 拿主模块
    // 这里给主模块基址（快捷且稳定）
    Base = PsGetProcessSectionBaseAddress(Process);
    if (Base) {
        Mod->Base = (ULONGLONG)Base;
        // ImageSize 从 PE 头读：MZ -> e_lfanew -> OptionalHeader.SizeOfImage
        __try {
