#include "rw.h"

static NTSTATUS GetProcessByPid(ULONG pid, PEPROCESS* out) {
    return PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, out);
}

static NTSTATUS DoCopy(ULONG pid, ULONGLONG addr, PVOID buf, ULONG size, BOOLEAN write) {
    PEPROCESS proc = NULL;
    NTSTATUS st = GetProcessByPid(pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T copied = 0;
    if (write) {
        st = MmCopyVirtualMemory(PsGetCurrentProcess(), buf, proc, (PVOID)addr, size, KernelMode, &copied);
    } else {
        st = MmCopyVirtualMemory(proc, (PVOID)addr, PsGetCurrentProcess(), buf, size, KernelMode, &copied);
    }
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS DispatchCreateClose(PDEVICE_OBJECT dev, PIRP irp) {
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    ULONG code = sp->Parameters.DeviceIoControl.IoControlCode;
    ULONG inLen = sp->Parameters.DeviceIoControl.InputBufferLength;
    ULONG outLen = sp->Parameters.DeviceIoControl.OutputBufferLength;
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG info = 0;

    if (code == IOCTL_RW_READ || code == IOCTL_RW_WRITE) {
        if (inLen >= sizeof(RW_REQ)) {
            PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
            if (code == IOCTL_RW_READ) {
                if (outLen >= req->size && req->size > 0) {
                    st = DoCopy(req->pid, req->addr, irp->AssociatedIrp.SystemBuffer, req->size, FALSE);
                    if (NT_SUCCESS(st)) info = req->size;
                }
            } else {
                if (outLen >= req->size && req->size > 0) {
                    st = DoCopy(req->pid, req->addr, (PUCHAR)irp->AssociatedIrp.SystemBuffer + sizeof(RW_REQ), req->size, TRUE);
                    if (NT_SUCCESS(st)) info = req->size;
                }
            }
        }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = info;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

