#include <cstdio>
#include <thread>
#include <chrono>

class KmBox {
public:
    bool Open(const wchar_t* port, DWORD baud = 115200) {
        h_ = CreateFileW(port, GENERIC_READ | GENERIC_WRITE, 0, nullptr,
                         OPEN_EXISTING, 0, nullptr);
        if (h_ == INVALID_HANDLE_VALUE) return false;

        DCB dcb{};
        dcb.DCBlength = sizeof(dcb);
        GetCommState(h_, &dcb);
        dcb.BaudRate = baud;
        dcb.ByteSize = 8;
        dcb.Parity   = NOPARITY;
        dcb.StopBits = ONESTOPBIT;
        dcb.fBinary  = TRUE;
        dcb.fParity  = FALSE;
        // 关掉流控，kmbox 侧通常不开握手
        dcb.fOutxCtsFlow = FALSE;
        dcb.fOutxDsrFlow = FALSE;
        dcb.fDtrControl  = DTR_CONTROL_DISABLE;
        dcb.fRtsControl  = RTS_CONTROL_DISABLE;
        dcb.fOutX = FALSE;
        dcb.fInX  = FALSE;
        SetCommState(h_, &dcb);

        COMMTIMEOUTS to{};
        to.WriteTotalTimeoutConstant   = 10;
        to.ReadIntervalTimeout         = 10;
        to.ReadTotalTimeoutConstant    = 10;
        SetCommTimeouts(h_, &to);
        PurgeComm(h_, PURGE_RXCLEAR | PURGE_TXCLEAR);
        return true;
    }

    // 鼠标相对移动：dx/dy 为像素增量，wheel 为滚轮
    bool Move(int dx, int dy, int wheel = 0) {
        // 常见 kmbox 相对移动报文（见下文协议段）
        uint8_t pkt[11];
        pkt[0] = 0x04;                 // 功能码：鼠标相对移动（不同固件见下表）
        pkt[1] = 0x00;
        *(int32_t*)(pkt + 2) = dx;
        *(int32_t*)(pkt + 6) = dy;
        pkt[10] = (uint8_t)(int8_t)wheel;
        return Write(pkt, sizeof(pkt));
    }

    // 鼠标按键：btn 位掩码 bit0=左 bit1=右 bit2=中
    bool Button(uint8_t mask) {
        uint8_t pkt[3] = { 0x05, 0x00, 0x00 };
        pkt[2] = mask;
        return Write(pkt, sizeof(pkt));
    }

private:
    bool Write(const uint8_t* buf, size_t n) {
        DWORD wr = 0;
        return WriteFile(h_, buf, (DWORD)n, &wr, nullptr) && wr == n;
    }
    HANDLE h_ = INVALID_HANDLE_VALUE;
};

int main() {
    KmBox box;
    if (!box.Open(L"\\\\.\\COM3")) {       // ← 换成你的端口
