static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* target = (argc > 1) ? argv[1] : L"[进程名].exe";
    DWORD pid = FindPid(target);
    if (!pid) { wprintf(L"[-] 没找到进程: %s\n", target); return 1; }

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess 失败: %lu\n", GetLastError()); return 1; }

    HMODULE mods[1024]; DWORD need = 0;
    if (!EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        wprintf(L"[-] EnumProcessModulesEx 失败: %lu\n", GetLastError());
        CloseHandle(h); return 1;
    }

    DWORD cnt = need / sizeof(HMODULE);
    wprintf(L"[+] PID=%lu  模块数=%lu\n", pid, cnt);
    wprintf(L"%-40s %-18s %-10s %s\n", L"模块", L"基址", L"大小", L"路径");
    for (DWORD i = 0; i < cnt; ++i) {
        MODULEINFO mi{};
        wchar_t path[MAX_PATH]{};
        if (!GetModuleInformation(h, mods[i], &mi, sizeof(mi))) continue;
        GetModuleFileNameExW(h, mods[i], path, MAX_PATH);
        wprintf(L"%-40s 0x%016llX 0x%08lX %s\n",
                path, (unsigned long long)mi.lpBaseOfDll, mi.SizeOfImage, path);
    }

    // 顺手把主模块基址打出来，后面算偏移直接用
    wchar_t mainPath[MAX_PATH]{};
    GetModuleFileNameExW(h, nullptr, mainPath, MAX_PATH);
    wprintf(L"\n[+] 主模块基址: 0x%016llX  (%s)\n",
            (unsigned long long)(uintptr_t)mods[0], mainPath);

    CloseHandle(h);
    return 0;
}
