```c
// 读链：base + off0 -> deref -> +off1 -> deref ... 直到拿到目标地址
uint64_t readPtr(HANDLE h, uint64_t addr) {
    uint64_t v = 0; SIZE_T rd = 0;
    if (!ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(v), &rd) || rd != sizeof(v)) return 0;
    return v;
}

uint64_t resolveChain(HANDLE h, uint64_t base, const uint32_t* offs, int n) {
    uint64_t addr = base;
    for (int i = 0; i < n; i++) {
        addr = readPtr(h, addr + offs[i]);
        if (!addr) return 0;
    }
    return addr;
}
