## 第一步：定位关键偏移

先跑这个扫描器，把模块基址和几个关键指针摸出来：

```cpp
// scan.cpp — 定位模块基址与候选指针
#include <windows.h>
#include <TlHelp32.h>
#include <cstdio>
#include <vector>
#include <cstring>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) {
        do { if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; } } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do { if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; } } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].exe";
    DWORD pid = GetPid(proc);
    if (!pid) { wprintf(L"process not found\n"); return 1; }
    uintptr_t base = GetModuleBase(pid, mod);
    wprintf(L"pid=%lu base=%p\n", pid, (void*)base);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess fail %lu\n", GetLastError()); return 1; }

    // 读 PE 头确认镜像
    IMAGE_DOS_HEADER dos{};
    ReadProcessMemory(h, (LPCVOID)base, &dos, sizeof(dos), nullptr);
    wprintf(L"e_magic=%04X\n", dos.e_magic);
    IMAGE_NT_HEADERS64 nt{};
    ReadProcessMemory(h, (LPCVOID)(base + dos.e_lfanew), &nt, sizeof(nt), nullptr);
    wprintf(L"sizeOfImage=%X textRVA=%X\n", nt.OptionalHeader.SizeOfImage, nt.OptionalHeader.BaseOfCode);
    CloseHandle(h);
    return 0;
}
```

