## 第二步：视图矩阵与坐标转换

```cpp
struct Matrix4x4 { float m[4][4]; };

struct Vec3 { float x, y, z; };

// 世界坐标 → 屏幕坐标。矩阵布局按目标游戏实测调整（行主序/列主序、offset 位置）
bool WorldToScreen(const Vec3& world, const Matrix4x4& vm, int screenW, int screenH, Vec3& out) {
    float w = vm.m[3][0]*world.x + vm.m[3][1]*world.y + vm.m[3][2]*world.z + vm.m[3][3];
    if (w < 0.01f) return false;
    float x = vm.m[0][0]*world.x + vm.m[0][1]*world.y + vm.m[0][2]*world.z + vm.m[0][3];
    float y = vm.m[1][0]*world.x + vm.m[1][1]*world.y + vm.m[1][2]*world.z + vm.m[1][3];
    out.x = (screenW / 2.0f) * (1.0f + x / w);
    out.y = (screenH / 2.0f) * (1.0f - y / w);
    out.z = w;
    return true;
}
```

