```cpp
// build: cl /std:c++17 /EHsc aim_stage0.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

// ---- 占位符：按你的目标填 ----
const wchar_t* PROC_NAME = L"[进程名].exe";   // 例 L"TslGame.exe"
const wchar_t* MOD_NAME  = L"[模块名].exe";   // 通常与进程同名
// -----------------------------

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

uintptr_t GetModBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod) || !_wcsicmp(me.szExePath, mod)) {
                base = (uintptr_t)me.modBaseAddr; break;
            }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain() {
    DWORD pid = GetPid(PROC_NAME);
    if (!pid) { printf("[-] process not found\n"); return 1; }
    printf("[+] pid = %lu (0x%lX)\n", pid, pid);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("[-] OpenProcess failed: %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModBase(pid, MOD_NAME);
    printf("[+] %ls base = 0x%llX\n", MOD_NAME, (unsigned long long)base);

    // 读 PE 头做一次真实读取验证
    IMAGE_DOS_HEADER dos{};
    SIZE_T rd = 0;
    if (ReadProcessMemory(h, (LPCVOID)base, &dos, sizeof(dos), &rd) && dos.e_magic == IMAGE_DOS_SIGNATURE) {
        IMAGE_NT_HEADERS nt{};
        ReadProcessMemory(h, (LPCVOID)(base + dos.e_lfanew), &nt, sizeof(nt), &rd);
        printf("[+] PE ok: MZ=%04X PE=%08X ImageBase=0x%llX SizeOfImage=0x%X\n",
               dos.e_magic, nt.Signature,
               (unsigned long long)nt.OptionalHeader.ImageBase,
               nt.OptionalHeader.SizeOfImage);
    } else {
        printf("[-] RPM failed or not a PE: err=%lu\n", GetLastError());
    }

    // 先备份原值用（改内存前 dump 原值）
    // 例：读 [base + 占位偏移] 的 DWORD
    // uint32_t orig = 0;
    // ReadProcessMemory(h, (LPCVOID)(base + [偏移]/ * 0x0 */), &orig, 4, &rd);
    // printf("[原值] 0x%08X\n", orig);
    // 若要写回：WriteProcessMemory(h, (LPCVOID)(base + [偏移]), &orig, 4, &rd);

    CloseHandle(h);
    return 0;
}
```

**跑通判据**：打印出 `PE ok` 且 `ImageBase` 与磁盘文件一致，说明 `OpenProcess` + `ReadProcessMemory` 可用——这一步只读，无副作用，不需要提前备份。

